use anyhow::{Context, Ok, Result};

use libcst_native::{Codegen, CodegenState};
use ruff_diagnostics::Edit;
use ruff_python_ast as ast;
use ruff_python_codegen::Stylist;
use ruff_python_literal::format::{FieldName, FieldType, FormatPart, FormatString, FromTemplate};
use ruff_python_semantic::Binding;
use ruff_python_trivia::{BackwardsTokenizer, SimpleTokenKind, SimpleTokenizer};
use ruff_text_size::Ranged;

use crate::cst::matchers::{match_call_mut, match_dict, match_expression, transform_expression};
use crate::Locator;

/// Generate a [`Edit`] to remove unused keys from format dict.
pub(super) fn remove_unused_format_arguments_from_dict(
    unused_arguments: &[usize],
    dict: &ast::ExprDict,
    locator: &Locator,
    stylist: &Stylist,
) -> Result<Edit> {
    let source_code = locator.slice(dict);
    transform_expression(source_code, stylist, |mut expression| {
        let dict = match_dict(&mut expression)?;

        // Remove the elements at the given indexes.
        let mut index = 0;
        dict.elements.retain(|_| {
            let is_unused = unused_arguments.contains(&index);
            index += 1;
            !is_unused
        });

        Ok(expression)
    })
    .map(|output| Edit::range_replacement(output, dict.range()))
}

/// Generate a [`Edit`] to remove unused keyword arguments from a `format` call.
pub(super) fn remove_unused_keyword_arguments_from_format_call(
    unused_arguments: &[usize],
    call: &ast::ExprCall,
    locator: &Locator,
    stylist: &Stylist,
) -> Result<Edit> {
    let source_code = locator.slice(call);
    transform_expression(source_code, stylist, |mut expression| {
        let call = match_call_mut(&mut expression)?;

        // Remove the keyword arguments at the given indexes.
        let mut index = 0;
        call.args.retain(|arg| {
            if arg.keyword.is_none() {
                return true;
            }

            let is_unused = unused_arguments.contains(&index);
            index += 1;
            !is_unused
        });

        Ok(expression)
    })
    .map(|output| Edit::range_replacement(output, call.range()))
}

/// Generate a [`Edit`] to remove unused positional arguments from a `format` call.
pub(crate) fn remove_unused_positional_arguments_from_format_call(
    unused_arguments: &[usize],
    call: &ast::ExprCall,
    locator: &Locator,
    stylist: &Stylist,
) -> Result<Edit> {
    let call_range = call.range();
    let contents = locator.contents();
    let source_start = usize::from(call_range.start());
    let source_end = usize::from(call_range.end());
    let source_code = &contents[source_start..source_end];

    let format_string = match &*call.func {
        ast::Expr::Attribute(attribute) => match &*attribute.value {
            ast::Expr::StringLiteral(string_literal) => {
                FormatString::from_str(string_literal.value.to_str()).ok()
            }
            _ => None,
        },
        _ => None,
    };

    let mut field_names: Vec<String> = Vec::new();
    if let Some(format_string) = format_string {
        for format_part in format_string.format_parts {
            if let FormatPart::Field { field_name, .. } = format_part {
                field_names.push(field_name);
            }
        }
    }

    let mut referenced_indexes: Vec<usize> = Vec::new();
    let mut auto_count = 0;
    for field_name in &field_names {
        if let Result::Ok(parsed) = FieldName::parse(field_name) {
            match parsed.field_type {
                FieldType::Auto => {
                    referenced_indexes.push(auto_count);
                    auto_count += 1;
                }
                FieldType::Index(index) => referenced_indexes.push(index),
                FieldType::Keyword(_) => {}
            }
        }
    }

    let mut indexes_to_remove: Vec<usize> = Vec::with_capacity(unused_arguments.len());
    for (index, argument) in call.arguments.args.iter().enumerate() {
        if unused_arguments.contains(&index) {
            if !argument.is_starred_expr() {
                if !referenced_indexes.contains(&index) {
                    indexes_to_remove.push(index);
                }
            }
        }
    }

    let wrapped_source = format!("({source_code})");
    let parsed_expression = match_expression(&wrapped_source)?;
    let expression = match parsed_expression {
        libcst_native::Expression::Call(mut cst_call) => {
            let mut argument_index = 0;
            cst_call.args.retain(|_| {
                let is_unused = indexes_to_remove.contains(&argument_index);
                argument_index += 1;
                !is_unused
            });
            libcst_native::Expression::Call(cst_call)
        }
        _ => anyhow::bail!("Expected Expression::Call"),
    };

    let mut state = CodegenState {
        default_newline: stylist.line_ending().as_str(),
        default_indent: stylist.indentation(),
        ..Default::default()
    };
    expression.codegen(&mut state);
    let mut generated = state.to_string();
    generated.drain(0..1);
    generated.drain(generated.len() - 1..generated.len());
    Ok(Edit::range_replacement(generated, call_range))
}

